"""Render backtest and audit results as markdown under docs/ (generated, do not edit by hand)."""

from __future__ import annotations

import json
import sqlite3

from . import config, db

HEADER = "<!-- Generated by `tennisscout report`. Do not edit by hand; re-run the pipeline instead. -->\n"


def _f(x, nd=4):
    return "–" if x is None else f"{x:.{nd}f}"


def _pct(x, nd=1):
    return "–" if x is None else f"{100 * x:.{nd}f}%"


def _metrics_table(rows: list[tuple[str, dict]]) -> list[str]:
    out = ["| Model | n | Accuracy | Brier | Log loss | ECE |", "|---|---:|---:|---:|---:|---:|"]
    for name, m in rows:
        if not m.get("n"):
            continue
        out.append(f"| {name} | {m['n']:,} | {_pct(m['accuracy'])} | {_f(m['brier'])} | {_f(m['log_loss'])} | {_f(m['ece'])} |")
    return out


def backtest_md(r: dict) -> str:
    v, t = r["validation_years"], r["test_years"]
    h = r["test_headline"]
    cfg = r["selected_config"]
    L = [HEADER, "# Backtest: pre-match surface Elo", ""]
    L += [
        f"Chronological replay of {r['n_scorable_matches']:,} tour-level singles matches (TML-Database, 1968 onward). "
        f"Each match is predicted from ratings that have absorbed only earlier matches, then it updates them. "
        f"Model choices were made on **{v[0]}–{v[1]}** (validation) and scored once on **{t[0]}–{t[1]}** (test).",
        "",
        "Excluded from both rating updates and scoring: walkovers, defaults, unknown results, and every row whose "
        "player identity failed a check (ID/name conflict, unknown or missing ID, placeholder player).",
        "",
        "## Test window, headline",
        "",
    ]
    L += _metrics_table([
        ("Coin flip", h["coin_flip"]),
        (f"Ranking logistic (β={h['ranking_logistic']['beta']:.3f}, fitted on validation)", h["ranking_logistic"]),
        ("Elo, overall only", h["elo_overall"]),
        ("Elo, 50/50 surface blend (FiveThirtyEight-style)", h["elo_538_blend"]),
        ("**Elo, selected on validation**", h["elo_selected"]),
    ])
    L += [
        "",
        "Lower is better for Brier, log loss and ECE (expected calibration error, 10 bins). "
        f"Market baseline: {r['market_baseline']}.",
        "",
        f"Selected model, completed matches only (retirements removed): "
        f"Brier {_f(r['test_selected_completed_only']['brier'])}, log loss {_f(r['test_selected_completed_only']['log_loss'])}, "
        f"n = {r['test_selected_completed_only']['n']:,}.",
        "",
        "## How the model was chosen",
        "",
        "Greedy forward selection: start from the FiveThirtyEight-style blend, try each single change, adopt the one "
        "that most improves **validation** log loss, repeat until nothing improves. Test numbers are shown for "
        "transparency only; they played no part in the choice.",
        "",
        "| Step | Validation log loss | Test log loss | Test Brier | Test ECE |",
        "|---|---:|---:|---:|---:|",
    ]
    for s in r["selection_steps"]:
        L.append(f"| {s['step']} | {_f(s['validation']['log_loss'], 5)} | {_f(s['test']['log_loss'], 5)} | {_f(s['test']['brier'], 5)} | {_f(s['test']['ece'])} |")
    L += [
        "",
        "Selected configuration: " + ", ".join(
            f"`{k}={cfg[k]}`" for k in ("surface_weight", "split_indoor_hard", "new_player_prior", "surface_init", "bo5_adjust", "pred_scale", "k_num", "k_offset", "k_shape")
        ) + ".",
        "",
        "<details><summary>Every candidate tried</summary>",
        "",
        "| From | Change | Validation log loss | Test log loss |",
        "|---|---|---:|---:|",
    ]
    for c in r["candidates_tried"]:
        L.append(f"| {c['from']} | {c['change']} | {_f(c['validation']['log_loss'], 5)} | {_f(c['test']['log_loss'], 5)} |")
    L += ["", "</details>", "", "## Calibration (selected model, test window)", "",
          "| Predicted | n | Mean prediction | Observed win rate |", "|---|---:|---:|---:|"]
    for b in r["test_calibration"]:
        L.append(f"| {b['lo']:.1f}–{b['hi']:.1f} | {b['n']:,} | {_f(b['mean_p'], 3)} | {_f(b['observed'], 3)} |")
    for title, key in (("By confidence grade", "test_by_confidence"), ("By tournament level", "test_by_level"),
                       ("By surface bucket", "test_by_bucket"), ("By best-of", "test_by_best_of"), ("By year", "test_by_year")):
        L += ["", f"## {title} (selected model, test window)", ""]
        L += _metrics_table(list(r[key].items()))
    L += [
        "",
        "Confidence grades: *high* = both players ≥ 50 prior tour matches and ≥ 15 on the surface; "
        "*medium* = both ≥ 15 overall; *low* = otherwise.",
        "",
    ]
    return "\n".join(L)


def audit_md(a: dict) -> str:
    pi, pt, cs, ss = a["population_identity"], a["population_timestamps"], a["cross_source"], a["sample_summary"]
    L = [HEADER, "# Data audit (first milestone)", ""]
    L += [f"Run at {a['run_at']}. Source snapshots:", ""]
    for s in a["snapshots"]:
        L.append(f"- `{s['snapshot_id']}`: {s['source']} revision {s['revision'][:12]} ({s['revision_date']}), collected {s['collected_at']}")
    L += ["", "## External services (probed live during the audit)", "", "| Service | URL | Reachable | Status / error |", "|---|---|---|---|"]
    for svc, probes in a["external_probes"].items():
        for p in probes:
            L.append(f"| {svc} | `{p['url'].split('?')[0]}` | {'yes' if p['reachable'] else 'no'} | {p['status'] or p['error']} |")
    L += ["", f"## Sample of {ss['n']} completed singles matches (2024–2025, stratified)", "",
          "Strata: " + ", ".join(f"{k} {v}" for k, v in ss["by_stratum"].items()) + ".", "",
          "| Check | Result |", "|---|---|"]
    rows = [
        ("Both players mapped to internal IDs", _pct(ss["both_players_internal_id"])),
        ("Identity check passed (ID and display name agree)", _pct(ss["identity_ok"])),
        ("Opponent, score and round present", _pct(ss["has_score_round"])),
        ("Serve/return stat line present", _pct(ss["has_serve_stats"])),
        ("Pre-match rankings present", _pct(ss["has_pre_match_ranks"])),
        ("Surface present", _pct(ss["has_surface"])),
        ("Indoor/outdoor flag present", f"{_pct(ss['has_indoor_flag'])} (tournament-level only; match-level roof status: {_pct(ss['indoor_flag_match_level'])})"),
        ("Altitude present", f"{_pct(ss['has_altitude_seed'])} (from the unverified manual venue seed)"),
        ("Outdoor matches with venue coordinates", f"{ss['outdoor_with_coordinates']} of {ss['outdoor_matches']}"),
        ("Outdoor matches with reconstructed weather joined", f"{ss['outdoor_weather_joined']} of {ss['outdoor_matches']}"),
        ("Event-time precision", ", ".join(f"{k}: {v}" for k, v in ss["event_time_precision"].items()) + f" (median window {ss['median_event_window_days']} days)"),
        ("Exact match date available (via linked MCP chart)", _pct(ss["exact_date_via_mcp"])),
        ("Start time of day available (via MCP)", _pct(ss["start_time_via_mcp"])),
        ("Publication timestamp", _pct(ss["has_publication_time"])),
        ("Collection timestamp", _pct(ss["has_collection_time"])),
        ("Point-by-point chart available", _pct(ss["point_by_point_available"])),
        ("Pre-match Elo prediction scored", _pct(ss["has_pre_match_prediction"])),
        ("Polymarket / Kalshi history checked", _pct(ss["market_history_checked"]) + " (hosts blocked; see probes)"),
    ]
    L += [f"| {k} | {v} |" for k, v in rows]
    st = pi["match_rows_by_identity_status"]
    L += ["", "## Identity (whole TML backbone)", "",
          "Match rows by identity status: " + ", ".join(f"{k} {v:,}" for k, v in sorted(st.items(), key=lambda kv: -kv[1])) + ". "
          "Rows that are not `ok` are kept in the database but excluded from ratings, training and scoring.", "",
          "ID/name conflicts (the source attached one player's ATP ID to another player's row):", ""]
    for c in pi["id_name_conflicts"]:
        L.append(f"- {c['year']} {c['tournament']} {c['round']}: {c['identity_note']}")
    L += ["", f"Homonyms among players with matches (same normalized name, different ATP IDs): {len(pi['homonym_names'])}, e.g. "
          + ", ".join(h["name"] for h in pi["homonym_names"][:8]) + ". Name lookups for these return all candidates.",
          "", f"Players seen under more than one display name: {pi['players_with_name_variants']:,}.", ""]
    L += ["## Timestamps (whole TML backbone)", "",
          "- Event-time precision: " + ", ".join(f"{k} {v:,}" for k, v in pt["event_time_precision"].items()) + ". "
          "Before 2026 the source dates only the tournament week, so each match's event time is a window.",
          f"- Rows with a publication timestamp: {pt['rows_with_publication_time']:,} of {pt['match_rows']:,}.",
          f"- Editions whose TML date is contradicted by exact-dated MCP charts: {pt['editions_with_dates_contradicted_by_mcp']}.",
          f"- Latest event in the mirror: {pt['latest_event_date']}.", ""]
    L += ["## Cross-source linking (Match Charting Project → internal IDs)", "",
          "| Link status | All years | 2019 on |", "|---|---:|---:|"]
    keys = sorted(set(cs["charts_all_years"]) | set(cs["charts_2019_on"]), key=lambda k: -cs["charts_all_years"].get(k, 0))
    for k in keys:
        L.append(f"| {k} | {cs['charts_all_years'].get(k, 0):,} | {cs['charts_2019_on'].get(k, 0):,} |")
    L += ["", "Player-name resolution: " + ", ".join(f"{k} {v:,}" for k, v in sorted(cs["player_name_resolution"].items(), key=lambda kv: -kv[1])) + ".",
          "",
          f"Of {cs['linked']:,} linked charts, {cs['linked_surface_disagreements']} disagree with TML about the surface "
          f"({cs['linked_hard_vs_carpet']} are MCP 'Hard' vs TML 'Carpet'), and {cs['linked_with_start_time']:,} carry a start time.",
          "", "Name variants resolved only because the match-level join was unique (candidates for `metadata/player_aliases.csv` after review):", ""]
    for f in cs["alias_suggestions_from_unique_joins"][:20]:
        L.append(f"- MCP “{f['name']}” → {f['tml_name']} (`{f['player_id']}`), {f['charts']} chart(s)")
    L.append("")
    return "\n".join(L)


def write(conn: sqlite3.Connection) -> list[str]:
    config.DOCS_DIR.mkdir(parents=True, exist_ok=True)
    written = []
    bt = db.get_meta(conn, "backtest_result")
    if bt:
        p = config.DOCS_DIR / "backtest.md"
        p.write_text(backtest_md(json.loads(bt)))
        written.append(str(p))
    au = db.get_meta(conn, "audit_result")
    if au:
        p = config.DOCS_DIR / "data-audit.md"
        p.write_text(audit_md(json.loads(au)))
        written.append(str(p))
    return written
